tool_input_args.value:
cat <<'SCRIPT' | node -
const fs = require('fs');
const path = require('path');

const sender = 'alice';
const recipient = 'bob';
const subject = 'Order Summary for 2026-09-02';

const content = `Hi Bob,

Here is the summary of the two orders from 2026-09-02:

1. ORD-6C71B1
   - Customer: Maya Chen
   - Date: 2026-09-02
   - Status: Cancelled
   - Items: Anker Portable Bluetooth Speaker
   - Total: $79

2. ORD-5B048F
   - Customer: Maya Chen
   - Date: 2026-09-02
   - Status: Confirmed
   - Items: Anker Portable Bluetooth Speaker, LogiTech Wireless Mouse M310
   - Total: $108

In short, ORD-6C71B1 was cancelled ($79) and ORD-5B048F was confirmed ($108).

Best regards,
Alice`;

const eml = [
  `From: ${sender}@example.com`,
  `To: ${recipient}@example.com`,
  `Subject: ${subject}`,
  `MIME-Version: 1.0`,
  `Content-Type: text/plain; charset="utf-8"`,
  ``,
  content
].join('\r\n');

const testbed = '/workspace/testbed';
for (const folder of [sender, recipient]) {
  const dir = path.join(testbed, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, `${subject}.eml`), eml);
}

console.log(`Successfully sent email to ${recipient}@example.com`);
SCRIPT
